<?php
function m6_data($answers='{"answer":4}') { return array('form_id'=>generate_stable_form_id('long-form'),'form_name'=>'long-form','participant_id'=>'7','form_responses'=>$answers,'created_at'=>current_time('mysql')); }
function m6_result($db) { return EIPSI_Submission_Storage_Service::attempt(m6_data()); }
