function m6_external($db,$callback){
 $external=new EIPSI_External_Database();$external->save_credentials('eipsi-m0-db','m0','m0-isolated','m6_external');
 $connection=new mysqli('eipsi-m0-db','m0','m0-isolated','m6_external');
 try{p0_assert($connection->query(EIPSI_Database_Schema_Manager::get_table_sql('vas_form_results'))!==false,'External fixture schema');$callback($external,$connection);}finally{$result=$connection->query('SHOW TABLES');while($row=$result->fetch_row()){if(strpos($row[0],$db->prefix)===0){$connection->query('DROP TABLE `'.$row[0].'`');}}$connection->close();}
}
