$tests['M6 filenames concurrentes reservan archivos distintos']=function($db){$dir='/tmp/eipsi-m6-files-'.bin2hex(random_bytes(6));mkdir($dir);$workers=array();$pipes=array();try{foreach(array(0,1)as$i){$workers[$i]=proc_open(array(PHP_BINARY,__DIR__.'/filename-worker.php',$dir,(string)$i),array(0=>array('pipe','r'),1=>array('pipe','w'),2=>array('file',$dir.'/log'.$i,'a')),$pipes[$i]);p0_assert(is_resource($workers[$i]),'Worker');fclose($pipes[$i][0]);}$deadline=microtime(true)+20;while(!file_exists($dir.'/ready0')||!file_exists($dir.'/ready1')){p0_assert(microtime(true)<$deadline,'Barrier');usleep(10000);}touch($dir.'/start');while(!file_exists($dir.'/result0')||!file_exists($dir.'/result1')){p0_assert(microtime(true)<$deadline,'Results');usleep(10000);}$r=array();foreach(array(0,1)as$i){$r[$i]=json_decode(file_get_contents($dir.'/result'.$i),true);p0_assert(empty($r[$i]['error']),$r[$i]['error']??'Error');$GLOBALS['p1c_exports'][]=EIPSI_FORMS_PLUGIN_DIR.'exports/'.$r[$i]['filename'];p0_assert(file_get_contents(end($GLOBALS['p1c_exports']))==='slot'.$i,'Overwrite');}p0_assert($r[0]['filename']!==$r[1]['filename'],'Collision');}finally{foreach($workers as$i=>$w){$state=proc_get_status($w);if($state['running']){proc_terminate($w);}fclose($pipes[$i][1]);proc_close($w);}foreach(glob($dir.'/*')as$p){unlink($p);}rmdir($dir);}};
