$tests['M6 facades conservan todas las firmas públicas congeladas']=function($db){require_once EIPSI_FORMS_PLUGIN_DIR.'admin/privacy-config.php';require_once EIPSI_FORMS_PLUGIN_DIR.'admin/services/class-device-data-service.php';require_once EIPSI_FORMS_PLUGIN_DIR.'admin/export.php';require_once EIPSI_FORMS_PLUGIN_DIR.'admin/services/class-access-log-export-service.php';$c=json_decode(file_get_contents(__DIR__.'/contracts.json'),true);$check=function($ref,$expected){p0_assert(array_map(function($p){return$p->getName();},$ref->getParameters())===$expected['parameters'],'Parameters: '.$ref->getName());p0_assert($ref->getNumberOfParameters()-$ref->getNumberOfRequiredParameters()===$expected['optional'],'Defaults: '.$ref->getName());};foreach($c['functions']as$name=>$sig){$check(new ReflectionFunction($name),$sig);}foreach($c['classes']as$class=>$methods){foreach($methods as$name=>$sig){$ref=new ReflectionMethod($class,$name);$check($ref,$sig);p0_assert($ref->isPublic()&&$ref->isStatic()===$sig['static'],'Visibility: '.$class.'::'.$name);}}};
$tests['M6 XLSX canónico conserva bytes originales']=function($db){$c=json_decode(file_get_contents(__DIR__.'/baseline-hashes.json'),true);p0_assert(hash_file('sha256',EIPSI_FORMS_PLUGIN_DIR.'lib/SimpleXLSXGen.php')===$c['files']['lib/SimpleXLSXGen.php'],'Library changed');};
foreach(array('IV termina en dos puntos'=>'abcdefghijklmno:','IV contiene delimitador'=>'abc::fghijklmnop')as$label=>$iv){$tests['M6 credenciales externas '.$label]=function($db)use($iv){$encrypted=openssl_encrypt('m0-isolated','aes-256-cbc',wp_salt('auth'),0,$iv);$GLOBALS['p0_options']['eipsi_external_db_enabled']=true;$GLOBALS['p0_options']['eipsi_external_db_host']='eipsi-m0-db';$GLOBALS['p0_options']['eipsi_external_db_user']='m0';$GLOBALS['p0_options']['eipsi_external_db_name']='m6_external';$GLOBALS['p0_options']['eipsi_external_db_password']=base64_encode($iv.'::'.$encrypted);$c=(new EIPSI_External_Database())->get_credentials();p0_assert($c['password']==='m0-isolated','Binary IV parser');};}
$tests['M6 handler wide CSV error de destino devuelve JSON controlado']=function($db){require_once EIPSI_FORMS_PLUGIN_DIR.'admin/ajax-export-handlers.php';$GLOBALS['p0_admin']=true;$_POST=array('nonce'=>'valid:eipsi_admin_nonce','study_id'=>3);$paths=array();foreach(array(-1,0,1)as$offset){$p=EIPSI_FORMS_PLUGIN_DIR.'exports/participantes-wide-3-'.date('Y-m-d_H-i-s',time()+$offset).'.csv';mkdir($p);$paths[]=$p;}try{$caught=false;try{eipsi_export_participants_wide_csv_handler();}catch(P0JsonResponse$e){$caught=true;p0_assert(!$e->success&&$e->status===500,'Wrong error envelope');}p0_assert($caught,'Missing JSON error');}finally{foreach($paths as$p){rmdir($p);}}};
$tests['M6 externo fallback y emergencia fallidos nunca confirman éxito']=function($db){(new EIPSI_External_Database())->save_credentials('eipsi-m0-db','m0','intentionally-wrong','m6_external');$db->query("DROP TABLE {$db->prefix}vas_form_results");$db->query("DROP TABLE {$db->prefix}eipsi_emergency_submissions");$db->query("CREATE TABLE {$db->prefix}eipsi_emergency_submissions (id BIGINT PRIMARY KEY)");$r=eipsi_safety_save_with_retry(m6_data(),1);p0_assert(!$r['success']&&!$r['insert_confirmed']&&$r['submission_id']===null,'All destinations failed but success returned');};
